      "body": "public class Board {\n    private final int size;\n    private final Mark[][] cells;\n    private int filled;\n\n    // O(1) win detection: one counter per line, per mark (index 0 = X, 1 = O).\n    private final int[][] rowCount;\n    private final int[][] colCount;\n    private final int[] diagCount;\n    private final int[] antiDiagCount;\n\n    public Board(int size) {\n        if (size < 2) throw new IllegalArgumentException(\"size must be >= 2\");\n        this.size = size;\n        this.cells = new Mark[size][size];\n        this.rowCount = new int[2][size];\n        this.colCount = new int[2][size];\n        this.diagCount = new int[2];\n        this.antiDiagCount = new int[2];\n    }\n\n    public int getSize() { return size; }\n\n    public Mark getCell(int row, int col) { return cells[row][col]; }\n\n    public boolean isFull() { return filled == size * size; }\n\n    public boolean isValidMove(int row, int col) {\n        return row >= 0 && row < size && col >= 0 && col < size && cells[row][col] == null;\n    }\n\n    // Validates before touching any state, so a rejected move changes nothing.\n    public void place(int row, int col, Mark mark) {\n        if (!isValidMove(row, col)) {\n            throw new IllegalArgumentException(\"Invalid move at (\" + row + \", \" + col + \")\");\n        }\n        cells[row][col] = mark;\n        filled++;\n    }\n\n    // Call once per placed mark. Returns true if that mark just completed a line.\n    boolean recordAndCheckWin(int row, int col, Mark mark) {\n        int m = mark.ordinal();\n        boolean won = false;\n\n        if (++rowCount[m][row] == size) won = true;\n        if (++colCount[m][col] == size) won = true;\n        if (row == col && ++diagCount[m] == size) won = true;\n        if (row + col == size - 1 && ++antiDiagCount[m] == size) won = true;\n\n        return won;\n    }\n\n    public String render() {\n        StringBuilder sb = new StringBuilder();\n        String separator = String.join(\"+\", java.util.Collections.nCopies(size, \"---\"));\n        for (int r = 0; r < size; r++) {\n            StringBuilder row = new StringBuilder();\n            for (int c = 0; c < size; c++) {\n                if (c > 0) row.append('|');\n                row.append(' ').append(cells[r][c] == null ? ' ' : cells[r][c].name().charAt(0)).append(' ');\n            }\n            sb.append(row).append('\\n');\n            if (r < size - 1) sb.append(separator).append('\\n');\n        }\n        return sb.toString();\n    }\n}"
