    "body": "public class Tests {\n    private static int passed = 0;\n\n    static void check(String name, boolean condition) {\n        if (!condition) throw new AssertionError(\"FAIL: \" + name);\n        passed++;\n        System.out.println(\"PASS: \" + name);\n    }\n\n    static void expectThrows(String name, Class<? extends Throwable> type, Runnable action) {\n        try {\n            action.run();\n        } catch (Throwable t) {\n            if (type.isInstance(t)) { passed++; System.out.println(\"PASS: \" + name); return; }\n            throw new AssertionError(\"FAIL: \" + name + \" threw \" + t);\n        }\n        throw new AssertionError(\"FAIL: \" + name + \" did not throw\");\n    }\n\n    static Game newGame(int size) {\n        return new Game(size, new Player(\"A\", Mark.X), new Player(\"B\", Mark.O));\n    }\n\n    static GameStatus play(Game g, int[][] moves) {\n        GameStatus s = null;\n        for (int[] m : moves) s = g.makeMove(m[0], m[1]);\n        return s;\n    }\n\n    public static void main(String[] args) {\n        // X: row 0 ; O: row 1 (O never completes)\n        Game row = newGame(3);\n        check(\"row win\", play(row, new int[][] { {0, 0}, {1, 0}, {0, 1}, {1, 1}, {0, 2} }) == GameStatus.WON\n                && row.getWinner().getMark() == Mark.X);\n\n        Game col = newGame(3);\n        check(\"column win\", play(col, new int[][] { {0, 1}, {0, 0}, {1, 1}, {1, 0}, {2, 1} }) == GameStatus.WON);\n\n        Game diag = newGame(3);\n        check(\"main diagonal win\", play(diag, new int[][] { {0, 0}, {0, 1}, {1, 1}, {0, 2}, {2, 2} }) == GameStatus.WON);\n\n        Game anti = newGame(3);\n        check(\"anti-diagonal win\", play(anti, new int[][] { {0, 2}, {0, 0}, {1, 1}, {0, 1}, {2, 0} }) == GameStatus.WON);\n\n        Game second = newGame(3);\n        check(\"second player can win\", play(second, new int[][] { {0, 0}, {1, 0}, {0, 1}, {1, 1}, {2, 2}, {1, 2} }) == GameStatus.WON\n                && second.getWinner().getName().equals(\"B\"));\n\n        Game draw = newGame(3);\n        check(\"draw when board is full\", play(draw, new int[][] {\n                {0, 0}, {0, 1}, {0, 2}, {1, 1}, {1, 0}, {2, 0}, {1, 2}, {2, 2}, {2, 1} }) == GameStatus.DRAW\n                && draw.getWinner() == null);\n\n        Game inProgress = newGame(3);\n        check(\"status stays IN_PROGRESS\", play(inProgress, new int[][] { {0, 0}, {1, 1} }) == GameStatus.IN_PROGRESS);\n\n        Game turns = newGame(3);\n        check(\"starts with first player\", turns.getCurrentPlayer().getName().equals(\"A\"));\n        turns.makeMove(0, 0);\n        check(\"turn alternates\", turns.getCurrentPlayer().getName().equals(\"B\"));\n\n        Game invalid = newGame(3);\n        invalid.makeMove(1, 1);\n        expectThrows(\"occupied cell rejected\", IllegalArgumentException.class, () -> invalid.makeMove(1, 1));\n        expectThrows(\"row out of bounds rejected\", IllegalArgumentException.class, () -> invalid.makeMove(3, 0));\n        expectThrows(\"negative column rejected\", IllegalArgumentException.class, () -> invalid.makeMove(0, -1));\n        check(\"rejected moves keep the turn\", invalid.getCurrentPlayer().getName().equals(\"B\"));\n        check(\"rejected moves leave the board unchanged\", invalid.render().equals(\n                \"   |   |   \\n---+---+---\\n   | X |   \\n---+---+---\\n   |   |   \\n\"));\n\n        Game over = newGame(3);\n        play(over, new int[][] { {0, 0}, {1, 0}, {0, 1}, {1, 1}, {0, 2} });\n        expectThrows(\"no moves after the game is over\", IllegalStateException.class, () -> over.makeMove(2, 2));\n\n        Game big = newGame(6);\n        check(\"6x6 row needs six marks\", play(big, new int[][] {\n                {0, 0}, {1, 0}, {0, 1}, {1, 1}, {0, 2}, {1, 2}, {0, 3}, {1, 3}, {0, 4}, {1, 4} }) == GameStatus.IN_PROGRESS);\n        check(\"6x6 row win on the sixth mark\", play(big, new int[][] { {0, 5} }) == GameStatus.WON\n                && big.getWinner().getName().equals(\"A\"));\n\n        Game fourBy = newGame(4);\n        check(\"4x4 anti-diagonal win\", play(fourBy, new int[][] {\n                {0, 3}, {0, 0}, {1, 2}, {0, 1}, {2, 1}, {0, 2}, {3, 0} }) == GameStatus.WON);\n\n        expectThrows(\"board smaller than 2 rejected\", IllegalArgumentException.class, () -> new Board(1));\n        expectThrows(\"players must use different marks\", IllegalArgumentException.class,\n                () -> new Game(3, new Player(\"A\", Mark.X), new Player(\"B\", Mark.X)));\n\n        System.out.println(passed + \" tests passed\");\n    }\n}",
