      "file": "SubscriberWorker.java",
      "body": "import java.util.concurrent.BlockingQueue;\nimport java.util.concurrent.LinkedBlockingQueue;\nimport java.util.concurrent.TimeUnit;\nimport java.util.function.BiConsumer;\nimport java.util.function.Predicate;\n\n// One queue and one thread per subscription: a slow subscriber only ever blocks itself,\n// and a single consumer thread per queue preserves publish order.\nclass SubscriberWorker implements Runnable {\n    private final Subscriber subscriber;\n    private final Predicate<Message> filter;\n    private final BiConsumer<Subscriber, Throwable> onError;\n    private final BlockingQueue<Message> queue = new LinkedBlockingQueue<>();\n    private volatile boolean running = true;\n\n    SubscriberWorker(Subscriber subscriber, Predicate<Message> filter, BiConsumer<Subscriber, Throwable> onError) {\n        this.subscriber = subscriber;\n        this.filter = filter;\n        this.onError = onError;\n    }\n\n    Subscriber subscriber() { return subscriber; }\n\n    // Evaluated on the publisher's thread, so a broken filter must never escape.\n    boolean accepts(Message m) {\n        try {\n            return filter.test(m);\n        } catch (RuntimeException e) {\n            onError.accept(subscriber, e);\n            return false;\n        }\n    }\n\n    void enqueue(Message m) { queue.offer(m); }\n\n    // Pending messages are still delivered before the thread exits.\n    void stop() { running = false; }\n\n    @Override\n    public void run() {\n        while (running || !queue.isEmpty()) {\n            try {\n                Message m = queue.poll(20, TimeUnit.MILLISECONDS);\n                if (m != null) subscriber.onMessage(m);\n            } catch (InterruptedException e) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (RuntimeException e) {\n                // isolate failures: report and carry on with the next message\n                onError.accept(subscriber, e);\n            }\n        }\n    }\n}"
