      "body": "import java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.TimeUnit;\nimport java.util.function.BiConsumer;\nimport java.util.function.Predicate;\n\npublic class Broker {\n    private final Map<String, Topic> topics = new ConcurrentHashMap<>();\n    private final Map<String, SubscriberWorker> workers = new ConcurrentHashMap<>(); // key: topic|subscriber\n    private final ExecutorService pool = Executors.newCachedThreadPool(r -> {\n        Thread t = new Thread(r);\n        t.setDaemon(true);\n        return t;\n    });\n    private final BiConsumer<Subscriber, Throwable> onError;\n    private volatile boolean closed;\n\n    public Broker() {\n        this((s, e) -> System.err.println(\"Subscriber \" + s.id() + \" failed: \" + e));\n    }\n\n    public Broker(BiConsumer<Subscriber, Throwable> onError) {\n        this.onError = onError;\n    }\n\n    public void createTopic(String name) {\n        topics.putIfAbsent(name, new Topic(name));\n    }\n\n    public void subscribe(String topicName, Subscriber subscriber) {\n        subscribe(topicName, subscriber, m -> true);\n    }\n\n    // Extensibility: a per-subscription filter decides which messages are delivered.\n    public void subscribe(String topicName, Subscriber subscriber, Predicate<Message> filter) {\n        ensureOpen();\n        Topic topic = require(topicName);\n        workers.computeIfAbsent(topicName + \"|\" + subscriber.id(), k -> {\n            SubscriberWorker w = new SubscriberWorker(subscriber, filter, onError);\n            topic.add(w);\n            pool.submit(w);\n            return w;\n        });\n    }\n\n    public void unsubscribe(String topicName, Subscriber subscriber) {\n        SubscriberWorker w = workers.remove(topicName + \"|\" + subscriber.id());\n        if (w != null) {\n            require(topicName).remove(w);\n            w.stop();\n        }\n    }\n\n    // Never blocks on a subscriber: it only appends to in-memory queues.\n    public void publish(String topicName, String payload) {\n        ensureOpen();\n        Message m = Message.of(topicName, payload);\n        for (SubscriberWorker w : require(topicName).subscribers()) {\n            if (w.accepts(m)) w.enqueue(m);\n        }\n    }\n\n    private Topic require(String name) {\n        Topic t = topics.get(name);\n        if (t == null) throw new IllegalArgumentException(\"Unknown topic \" + name);\n        return t;\n    }\n\n    private void ensureOpen() {\n        if (closed) throw new IllegalStateException(\"Broker is shut down\");\n    }\n\n    // Stops accepting work, lets every queue drain, then waits for the workers to finish.\n    public void shutdown() throws InterruptedException {\n        closed = true;\n        workers.values().forEach(SubscriberWorker::stop);\n        pool.shutdown();\n        pool.awaitTermination(10, TimeUnit.SECONDS);\n    }\n}"
