    "file": "Main.java",
    "body": "import java.util.List;\nimport java.util.concurrent.CountDownLatch;\nimport java.util.concurrent.atomic.AtomicInteger;\nimport java.util.stream.Collectors;\nimport java.util.stream.IntStream;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        AtomicInteger failures = new AtomicInteger();\n        Broker broker = new Broker((s, e) -> failures.incrementAndGet());\n        Publisher publisher = new Publisher(broker);\n\n        System.out.println(\"== 1. Every subscriber gets every message ==\");\n        broker.createTopic(\"orders\");\n        CollectingSubscriber billing = new CollectingSubscriber(\"billing\");\n        CollectingSubscriber email = new CollectingSubscriber(\"email\");\n        broker.subscribe(\"orders\", billing);\n        broker.subscribe(\"orders\", email);\n        publisher.publish(\"orders\", \"order-1 created\");\n        publisher.publish(\"orders\", \"order-2 created\");\n        billing.awaitCount(2, 2000);\n        email.awaitCount(2, 2000);\n        System.out.println(\"billing: \" + billing.received());\n        System.out.println(\"email:   \" + email.received());\n\n        System.out.println();\n        System.out.println(\"== 2. Unsubscribe stops delivery ==\");\n        broker.unsubscribe(\"orders\", email);\n        publisher.publish(\"orders\", \"order-3 created\");\n        billing.awaitCount(3, 2000);\n        System.out.println(\"billing: \" + billing.received());\n        System.out.println(\"email:   \" + email.received() + \"  (unchanged)\");\n\n        System.out.println();\n        System.out.println(\"== 3. A slow and a failing subscriber do not affect the others ==\");\n        broker.createTopic(\"payments\");\n        CountDownLatch release = new CountDownLatch(1);\n        CollectingSubscriber slow = new CollectingSubscriber(\"slow\", m -> {\n            try { release.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n        CollectingSubscriber flaky = new CollectingSubscriber(\"flaky\", m -> {\n            if (m.payload().equals(\"bad\")) throw new IllegalStateException(\"cannot handle \" + m.payload());\n        });\n        CollectingSubscriber fast = new CollectingSubscriber(\"fast\");\n        broker.subscribe(\"payments\", slow);\n        broker.subscribe(\"payments\", flaky);\n        broker.subscribe(\"payments\", fast);\n        publisher.publish(\"payments\", \"p1\");\n        publisher.publish(\"payments\", \"bad\");\n        publisher.publish(\"payments\", \"p3\");\n        fast.awaitCount(3, 2000);\n        flaky.awaitCount(2, 2000);\n        System.out.println(\"fast:  \" + fast.received() + \"   (slow subscriber still blocked)\");\n        System.out.println(\"flaky: \" + flaky.received() + \"   (failures so far: \" + failures.get() + \")\");\n        System.out.println(\"slow:  \" + slow.received());\n        release.countDown();\n        slow.awaitCount(3, 2000);\n        System.out.println(\"slow after release: \" + slow.received());\n\n        System.out.println();\n        System.out.println(\"== 4. Per-subscriber publish order ==\");\n        broker.createTopic(\"ticks\");\n        CollectingSubscriber ordered = new CollectingSubscriber(\"ordered\");\n        broker.subscribe(\"ticks\", ordered);\n        for (int i = 1; i <= 20; i++) publisher.publish(\"ticks\", String.valueOf(i));\n        ordered.awaitCount(20, 2000);\n        List<String> expected = IntStream.rangeClosed(1, 20).mapToObj(String::valueOf).collect(Collectors.toList());\n        System.out.println(\"received 20 messages in publish order: \" + ordered.received().equals(expected));\n\n        System.out.println();\n        System.out.println(\"== 5. Filtered subscription ==\");\n        broker.createTopic(\"alerts\");\n        CollectingSubscriber eu = new CollectingSubscriber(\"eu-team\");\n        CollectingSubscriber all = new CollectingSubscriber(\"all-regions\");\n        broker.subscribe(\"alerts\", eu, m -> m.payload().startsWith(\"EU:\"));\n        broker.subscribe(\"alerts\", all);\n        publisher.publish(\"alerts\", \"EU: disk full\");\n        publisher.publish(\"alerts\", \"US: cpu high\");\n        publisher.publish(\"alerts\", \"EU: latency\");\n        all.awaitCount(3, 2000);\n        eu.awaitCount(2, 2000);\n        System.out.println(\"eu-team:     \" + eu.received());\n        System.out.println(\"all-regions: \" + all.received());\n\n        System.out.println();\n        System.out.println(\"== 6. Unknown topic and shutdown ==\");\n        try {\n            publisher.publish(\"nope\", \"x\");\n        } catch (IllegalArgumentException e) {\n            System.out.println(\"Rejected: \" + e.getMessage());\n        }\n        broker.shutdown();\n        try {\n            publisher.publish(\"orders\", \"late\");\n        } catch (IllegalStateException e) {\n            System.out.println(\"Rejected: \" + e.getMessage());\n        }\n    }\n}",
