          "file": "LeastLoadedStrategy.java",
          "body": "import java.util.List;\n\n// An alternative algorithm that spreads work: fewest pending stops wins, distance breaks ties.\npublic class LeastLoadedStrategy implements DispatchStrategy {\n    @Override\n    public Elevator choose(List<Elevator> elevators, Request req) {\n        Elevator best = null;\n        for (Elevator e : elevators) {\n            if (best == null\n                    || e.pendingStops() < best.pendingStops()\n                    || (e.pendingStops() == best.pendingStops()\n                        && Math.abs(e.floor() - req.floor()) < Math.abs(best.floor() - req.floor()))) {\n                best = e;\n            }\n        }\n        return best;\n    }\n}"
