      "file": "ElevatorController.java",
      "body": "import java.util.ArrayList;\nimport java.util.List;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.ScheduledExecutorService;\nimport java.util.concurrent.TimeUnit;\nimport java.util.function.Consumer;\nimport java.util.stream.Collectors;\n\npublic class ElevatorController {\n    private final int floors;\n    private final List<Elevator> elevators = new ArrayList<>();\n    private DispatchStrategy strategy;\n    private Consumer<StopEvent> listener = e -> { };\n    private long tickCount;\n    private ScheduledExecutorService ticker;\n\n    public ElevatorController(int floors, int elevatorCount, DispatchStrategy strategy) {\n        if (floors < 2) throw new IllegalArgumentException(\"need at least 2 floors\");\n        if (elevatorCount < 1) throw new IllegalArgumentException(\"need at least 1 elevator\");\n        this.floors = floors;\n        this.strategy = strategy;\n        for (int i = 0; i < elevatorCount; i++) elevators.add(new Elevator(i, 0));\n    }\n\n    // Dispatch decisions are serialised so concurrent requests see a consistent view of the cars.\n    public synchronized int requestElevator(int floor, Direction direction) {\n        checkFloor(floor);\n        if (direction == Direction.IDLE) throw new IllegalArgumentException(\"a request must be UP or DOWN\");\n        if (direction == Direction.UP && floor == floors - 1) throw new IllegalArgumentException(\"cannot go up from the top floor\");\n        if (direction == Direction.DOWN && floor == 0) throw new IllegalArgumentException(\"cannot go down from the ground floor\");\n\n        List<Elevator> available = elevators.stream().filter(Elevator::isInService).collect(Collectors.toList());\n        if (available.isEmpty()) throw new IllegalStateException(\"No elevator in service\");\n\n        Elevator e = strategy.choose(available, new Request(floor, direction));\n        e.addStop(floor);\n        return e.id();\n    }\n\n    public synchronized void selectFloor(int elevatorId, int destination) {\n        checkFloor(destination);\n        elevator(elevatorId).addStop(destination);\n    }\n\n    // One unit of time: every car moves one floor. Returns the stops made during this tick.\n    public synchronized List<StopEvent> tick() {\n        tickCount++;\n        List<StopEvent> events = new ArrayList<>();\n        for (Elevator e : elevators) {\n            if (e.step()) {\n                StopEvent event = new StopEvent(tickCount, e.id(), e.floor());\n                events.add(event);\n                listener.accept(event);\n            }\n        }\n        return events;\n    }\n\n    public synchronized boolean isIdle() {\n        return elevators.stream().allMatch(Elevator::isIdle);\n    }\n\n    public synchronized long ticks() { return tickCount; }\n    public synchronized void setStrategy(DispatchStrategy strategy) { this.strategy = strategy; }\n    public synchronized void onStop(Consumer<StopEvent> listener) { this.listener = listener; }\n    public synchronized void setInService(int elevatorId, boolean inService) { elevator(elevatorId).setInService(inService); }\n\n    public synchronized String status() {\n        return elevators.stream().map(e -> {\n            char dir = e.direction() == Direction.UP ? '^' : e.direction() == Direction.DOWN ? 'v' : '.';\n            return \"E\" + e.id() + \"@\" + e.floor() + dir + (e.isInService() ? \"\" : \"(off)\");\n        }).collect(Collectors.joining(\" \"));\n    }\n\n    // Real-time mode: tick on a background thread instead of calling tick() by hand.\n    public synchronized void start(long periodMillis) {\n        if (ticker != null) return;\n        ticker = Executors.newSingleThreadScheduledExecutor(r -> {\n            Thread t = new Thread(r, \"elevator-ticker\");\n            t.setDaemon(true);\n            return t;\n        });\n        ticker.scheduleAtFixedRate(this::tick, 0, periodMillis, TimeUnit.MILLISECONDS);\n    }\n\n    public synchronized void stop() {\n        if (ticker != null) { ticker.shutdownNow(); ticker = null; }\n    }\n\n    private Elevator elevator(int id) {\n        if (id < 0 || id >= elevators.size()) throw new IllegalArgumentException(\"No elevator \" + id);\n        return elevators.get(id);\n    }\n\n    private void checkFloor(int floor) {\n        if (floor < 0 || floor >= floors) throw new IllegalArgumentException(\"Floor \" + floor + \" does not exist\");\n    }\n}"
