          "file": "WeekendSurcharge.java",
          "body": "import java.time.DayOfWeek;\nimport java.time.LocalDate;\n\n// Decorates another strategy: +20% of the daily rate for every planned Saturday and Sunday.\npublic class WeekendSurcharge implements PricingStrategy {\n    private final PricingStrategy inner;\n\n    public WeekendSurcharge(PricingStrategy inner) { this.inner = inner; }\n\n    @Override\n    public long totalCents(Reservation r) {\n        long rate = r.getVehicle().getType().dailyRateCents();\n        long weekendDays = 0;\n        for (LocalDate d = r.getFrom(); d.isBefore(r.getTo()); d = d.plusDays(1)) {\n            if (d.getDayOfWeek() == DayOfWeek.SATURDAY || d.getDayOfWeek() == DayOfWeek.SUNDAY) weekendDays++;\n        }\n        return inner.totalCents(r) + Math.round(rate * 0.2) * weekendDays;\n    }\n}"
