          "file": "CardPayment.java",
          "body": "import java.util.concurrent.atomic.AtomicInteger;\n\npublic class CardPayment implements PaymentMethod {\n    private static final AtomicInteger SEQUENCE = new AtomicInteger();\n\n    private final String last4;\n    private final long limitCents;\n\n    public CardPayment(String last4, long limitCents) {\n        this.last4 = last4;\n        this.limitCents = limitCents;\n    }\n\n    @Override\n    public PaymentResult pay(Customer customer, long amountCents) {\n        if (amountCents > limitCents) {\n            return new PaymentResult(false, null, \"Card ending \" + last4 + \" declined: over limit\");\n        }\n        return new PaymentResult(true, \"CARD-\" + SEQUENCE.incrementAndGet(), \"Charged card ending \" + last4);\n    }\n}"
