      "file": "Reservation.java",
      "body": "import java.time.LocalDate;\nimport java.util.concurrent.atomic.AtomicInteger;\n\npublic class Reservation {\n    private static final AtomicInteger SEQUENCE = new AtomicInteger();\n\n    private final String id = \"R-\" + SEQUENCE.incrementAndGet();\n    private final Customer customer;\n    private final Vehicle vehicle;\n    private final LocalDate from;\n    private final LocalDate to;\n    private ReservationStatus status = ReservationStatus.RESERVED;\n    private LocalDate returnedOn;\n\n    public Reservation(Customer customer, Vehicle vehicle, LocalDate from, LocalDate to) {\n        this.customer = customer;\n        this.vehicle = vehicle;\n        this.from = from;\n        this.to = to;\n    }\n\n    public synchronized boolean isActive() {\n        return status == ReservationStatus.RESERVED || status == ReservationStatus.PICKED_UP;\n    }\n\n    // Half-open ranges [from, to): back-to-back rentals do not overlap.\n    public boolean overlaps(LocalDate otherFrom, LocalDate otherTo) {\n        return from.isBefore(otherTo) && otherFrom.isBefore(to);\n    }\n\n    public synchronized void pickUp() {\n        require(ReservationStatus.RESERVED);\n        status = ReservationStatus.PICKED_UP;\n    }\n\n    public synchronized void complete(LocalDate returnDate) {\n        require(ReservationStatus.PICKED_UP);\n        if (returnDate.isBefore(from)) throw new IllegalArgumentException(\"Return date is before the rental started\");\n        returnedOn = returnDate;\n        status = ReservationStatus.COMPLETED;\n    }\n\n    public synchronized void cancel() {\n        require(ReservationStatus.RESERVED);\n        status = ReservationStatus.CANCELLED;\n    }\n\n    private void require(ReservationStatus expected) {\n        if (status != expected) {\n            throw new IllegalStateException(\"Expected \" + expected + \" but was \" + status);\n        }\n    }\n\n    public String getId() { return id; }\n    public Customer getCustomer() { return customer; }\n    public Vehicle getVehicle() { return vehicle; }\n    public LocalDate getFrom() { return from; }\n    public LocalDate getTo() { return to; }\n    public synchronized LocalDate getReturnedOn() { return returnedOn; }\n    public synchronized ReservationStatus getStatus() { return status; }\n}"
